ShellControllerAsyncWaiter::ShellControllerAsyncWaiter(
    ShellController* proxy) : proxy_(proxy) {}

ShellControllerAsyncWaiter::~ShellControllerAsyncWaiter() = default;


void ShellControllerAsyncWaiter::GetSwitchValue(
    const std::string& name, std::optional<std::string>* out_value) {
  base::RunLoop loop;
  proxy_->GetSwitchValue(
      std::move(name),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::optional<std::string>* out_value
,
             const std::optional<std::string>& value) {*out_value = std::move(value);
            loop->Quit();
          },
          &loop,
          out_value));
  loop.Run();
}

std::optional<std::string> ShellControllerAsyncWaiter::GetSwitchValue(
    const std::string& name) {
  std::optional<std::string> async_wait_result;
  GetSwitchValue(std::move(name),&async_wait_result);
  return async_wait_result;
}

void ShellControllerAsyncWaiter::ExecuteJavaScript(
    const ::std::u16string& script, ::base::Value* out_value) {
  base::RunLoop loop;
  proxy_->ExecuteJavaScript(
      std::move(script),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::base::Value* out_value
,
             ::base::Value value) {*out_value = std::move(value);
            loop->Quit();
          },
          &loop,
          out_value));
  loop.Run();
}

::base::Value ShellControllerAsyncWaiter::ExecuteJavaScript(
    const ::std::u16string& script) {
  ::base::Value async_wait_result;
  ExecuteJavaScript(std::move(script),&async_wait_result);
  return async_wait_result;
}






